import heapq


def _ledger(revision_priority, tax_base):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if revision_priority == "sequence_first":
                key = (sequence, event.get("revision", 0), position)
            else:
                key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([None] + versions)

    best_vector = None
    best = None
    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name) is None or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        invalid = False
        graph = {name: [] for name, value in selected.items() if value is not None}
        for name, version in selected.items():
            if version is None:
                continue
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                invalid = True
                break
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = selected[other]
                if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                    invalid = True
                    break
                graph[name].append(other)
            if invalid:
                break
        if invalid:
            continue

        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(graph[name])
        installed = {name for name, version in selected.items() if version is not None}
        if closure != installed:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in graph[name]:
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in graph):
            continue

        vector = tuple(selected[name] if selected[name] is not None else -1
                       for name in sorted(names, reverse=True))
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: version for name, version in selected.items()
                    if version is not None}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    options = [job for job in jobs if job["id"] not in blocked]
    best_ids = None
    best_value = None

    for chosen in combinations(options, k):
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        timeline = []
        for job in chosen:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = 0
        overlap_ok = True
        for _, change in sorted(timeline):
            active += change
            if active > 2:
                overlap_ok = False
                break
        if not overlap_ok:
            continue

        sorted_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in chosen)
        if (best_ids is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_ids, best_value = sorted_ids, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit_for.get(start_node, 0)
    start_time = data["start"]
    start_state = (start_node, start_mask, data["coupons"])
    distances = {start_state: start_time}
    queue = [(start_time, start_node, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            next_mask = mask | bit_for.get(edge["v"], 0)
            for duration, remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"], next_mask, remaining))
    return {"arrival": None}


